"""Build the Carmen Wilde Fine Art static site from audited public catalog data."""
from pathlib import Path
from html import escape
import json, re
ROOT=Path(__file__).parent
products=json.loads((ROOT/'products.json').read_text())
source=(ROOT/'index.html').read_text()
css=source.split('<style>',1)[1].split('</style>',1)[0] if '<style>' in source else (ROOT/'styles.css').read_text()
if '<style>' in source:
    css+='''
.page-hero{padding:96px 0 55px;max-width:950px}.page-hero h1{font:clamp(65px,8vw,115px)/.95 'Instrument Serif',Georgia,serif;letter-spacing:-.035em;font-weight:400;margin:24px 0}.page-hero h1 em{color:#497568;font-weight:400}.page-hero p{max-width:650px;font-size:17px;line-height:1.75;color:#56645c}.small-note{color:#64736a;font-size:12px;line-height:1.7}.catalog-nav{display:flex;gap:28px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0;margin:20px 0 45px;flex-wrap:wrap}.catalog-nav a{font-size:11px;text-transform:uppercase;letter-spacing:.17em;font-weight:600}.catalog-nav a.active{color:var(--pine);text-decoration:underline;text-underline-offset:8px}.catalog{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:54px 23px;padding-bottom:100px}.product-card{min-width:0}.product-card .image{display:flex;align-items:center;justify-content:center;height:345px;background:#e9e8e1;overflow:hidden}.product-card img{width:100%;height:100%;object-fit:contain;transition:transform .3s}.product-card:hover img{transform:scale(1.025)}.product-card h2{font:25px/1.15 'Instrument Serif',Georgia,serif;font-weight:400;margin:15px 0 4px}.product-card p{margin:0;color:#617067;font-size:12px}.section-space{padding:45px 0 115px}.prose{max-width:700px;font-size:16px;line-height:1.85;color:#4d5b54}.prose h2{font:40px/1.15 'Instrument Serif',Georgia,serif;color:var(--ink);font-weight:400;margin:45px 0 12px}.prose a{text-decoration:underline;text-underline-offset:4px}.split{display:grid;grid-template-columns:1fr 1fr;gap:min(8vw,100px);align-items:center}.split-art{width:100%;height:560px;object-fit:cover}.portrait{max-height:560px;object-fit:contain;object-position:bottom;background:#e9e8e1}.rule{border:0;border-top:1px solid var(--line);margin:52px 0}.pill-link{display:inline-flex;background:var(--pine);color:white;min-height:54px;align-items:center;padding:0 25px;font-size:11px;letter-spacing:.15em;text-transform:uppercase;font-weight:600}.pill-link:hover{background:#376c5f}.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:8%;padding-bottom:120px}.contact-grid .prose{margin-top:0}.form-row{display:grid;gap:18px;margin-top:25px}.form-row label{font-size:11px;text-transform:uppercase;letter-spacing:.14em;font-weight:600}.form-row input,.form-row textarea{font:16px 'DM Sans',sans-serif;margin-top:9px;width:100%;padding:16px;background:var(--white);border:1px solid var(--line);border-radius:0;color:var(--ink)}.form-row textarea{height:155px;resize:vertical}.form-row button{border:0;cursor:pointer;justify-content:center;width:max-content}.details{display:grid;grid-template-columns:1.1fr .9fr;gap:8%;padding:75px 0 120px;align-items:start}.details img{width:100%;max-height:750px;object-fit:contain;background:#e9e8e1}.details h1{font:clamp(54px,6vw,85px)/1 'Instrument Serif',Georgia,serif;font-weight:400;margin:20px 0}.details .price{font-size:21px}.details .prose{white-space:pre-line;overflow-wrap:anywhere}.detail-actions{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin-top:30px}.detail-actions .textlink{padding:12px 0}.faq-item{border-top:1px solid var(--line);padding:25px 0}.faq-item summary{font:26px 'Instrument Serif',Georgia,serif;cursor:pointer;list-style:none}.faq-item summary::after{content:'+';float:right;font:20px 'DM Sans',sans-serif}.faq-item[open] summary::after{content:'−'}.faq-item p{line-height:1.7;color:#536059}.site-note{background:#e5eae3;padding:22px 27px;margin:0 0 30px;color:#3d5148;font-size:13px;line-height:1.7}.legal{padding-bottom:100px}.site-footer-links{display:flex;gap:18px;flex-wrap:wrap}
@media(max-width:900px){.catalog{grid-template-columns:repeat(2,minmax(0,1fr))}.product-card .image{height:315px}}
@media(max-width:680px){.page-hero{padding:60px 0 30px}.page-hero h1{font-size:65px}.page-hero p{font-size:15px}.catalog{gap:32px 13px}.product-card .image{height:220px}.product-card h2{font-size:22px}.split,.contact-grid,.details{grid-template-columns:1fr;gap:35px}.split-art{height:350px}.details{padding:45px 0 80px}.details img{max-height:520px}.footer-links{gap:19px}.site-footer-links{margin-top:28px}}
@media(max-width:390px){.product-card .image{height:190px}}
'''
(ROOT/'styles.css').write_text(css)
FONT='<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">'
NAV=[('Home','index.html'),('The work','portfolio.html'),('Browse originals','originals.html'),('Browse minis','minis.html'),('Commissions','commissions.html'),('Rentals','rentals.html'),('About','about.html'),('Contact','contact.html')]
def header(depth=0):
 p='../'*depth
 links=''.join(f'<a href="{p}{url}">{label}</a>' for label,url in NAV[1:])
 return f'''<header class="shell top"><a class="brand" href="{p}index.html" aria-label="Carmen Wilde Fine Art home">Carmen Wilde<span>Fine Art</span></a><button class="menu-toggle" type="button" aria-controls="main-nav" aria-expanded="false">Menu ☰</button><nav class="nav" id="main-nav" aria-label="Main navigation">{links}</nav></header>'''
def footer(depth=0):
 p='../'*depth
 links=''.join(f'<a href="{p}{url}">{label}</a>' for label,url in [('Portfolio','portfolio.html'),('Originals','originals.html'),('Mini paintings','minis.html'),('FAQ','faq.html'),('Shipping & returns','shipping-returns.html'),('Terms','terms-conditions.html'),('Contact','contact.html')])
 return f'''<footer class="footer shell"><div class="footer-main"><a class="brand" href="{p}index.html">Carmen Wilde<span>Fine Art</span></a><div class="footer-links site-footer-links">{links}</div></div><div class="footer-bottom"><span>© Carmen Wilde Fine Art · Edmonton, Alberta</span><span><a href="https://www.instagram.com/carmen_wilde_fine_art/" target="_blank" rel="noopener noreferrer">Instagram ↗</a> · <a href="https://www.facebook.com/carmen.wilde.9/" target="_blank" rel="noopener noreferrer">Facebook ↗</a></span></div></footer>'''
JS='''<script>const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Close ✕':'Menu ☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='Menu ☰'}));</script>'''
def page(title,content,depth=0,desc='Original landscape paintings by Edmonton artist Carmen Wilde.',switcher=False):
 p='../'*depth
 review_css='<link rel="stylesheet" href="concepts/design-switcher.css">' if switcher else ''
 review_control='''<aside class="design-switcher" aria-label="Design preview switcher"><div class="design-switcher__label"><small>Design 1 of 3</small><strong>Original preview</strong></div><a class="design-switcher__next" href="concepts/gallery-window.html" aria-label="Next design: Exhibition">Next design ↗</a></aside>''' if switcher else ''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{escape(desc,quote=True)}"><title>{escape(title)} | Carmen Wilde Fine Art</title>{FONT}<link rel="stylesheet" href="{p}styles.css">{review_css}</head><body>{header(depth)}<main id="top">{content}</main>{footer(depth)}{review_control}{JS}</body></html>'''
def save(name,title,body,depth=0,desc=None,switcher=False):
 dest=ROOT/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(page(title,body,depth,desc or title+' by Edmonton landscape artist Carmen Wilde.',switcher=switcher))
def hero(kicker,title,lead):return f'<section class="shell page-hero"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{lead}</p></section>'
def price(x):
 try:return f'CAD ${float(x["price"]):,.2f}' if float(x['price'])>0 else 'Price on request'
 except:return 'Price on request'
def card(x,depth=0):
 p='../'*depth
 return f'''<article class="product-card"><a class="image" href="{p}art/{escape(x['slug'])}.html"><img src="{p}{escape(x['image'])}" alt="{escape(x['name'],quote=True)} painting by Carmen Wilde" loading="lazy"></a><h2><a href="{p}art/{escape(x['slug'])}.html">{escape(x['name'])}</a></h2><p>{price(x)}</p></article>'''
mini=[x for x in products if x['slug'].startswith('mini')]
originals=[x for x in products if x not in mini]
for filename,kicker,title,lead,items,active in [
 ('originals.html','Original paintings','Bring the <em>wild home.</em>','Browse Carmen’s larger original works. Availability and final pricing are confirmed through the current store before purchase.',originals,'originals.html'),
 ('minis.html','Small canvas collection','A little piece of <em>the wild.</em>','Original mini paintings, often 8 × 10 inches. Browse the collection and confirm current availability before purchase.',mini,'minis.html')]:
 nav='<div class="catalog-nav"><a class="'+('active' if active=='originals.html' else '')+'" href="originals.html">Originals</a><a class="'+('active' if active=='minis.html' else '')+'" href="minis.html">Mini paintings</a><a href="portfolio.html">Portfolio</a></div>'
 body=hero(kicker,title,lead)+f'<div class="shell">{nav}<p class="small-note">This catalog reflects the current public listings. Some works may have sold; check the linked store or contact Carmen before ordering.</p><div class="catalog">'+''.join(card(x) for x in items)+'</div></div>'
 save(filename,'Original paintings' if active=='originals.html' else 'Mini paintings',body,desc='Explore Carmen Wilde’s original acrylic paintings and fine art available for inquiry.')
for x in products:
 p='art/'+x['slug']+'.html'
 buy=f'<a class="button" href="{escape(x["legacy_url"],quote=True)}" target="_blank" rel="noopener noreferrer">View on current store <span aria-hidden="true">↗</span></a>'
 inquiry='mailto:cwildedesigns@shaw.ca?subject='+escape('Artwork inquiry: '+x['name'],quote=True).replace(' ','%20')
 label='Mini paintings' if x in mini else 'Original paintings';listing='minis.html' if x in mini else 'originals.html'
 body=f'''<section class="shell details"><div><img src="../{escape(x['image'])}" alt="{escape(x['name'],quote=True)} original painting by Carmen Wilde"></div><div><span class="eyebrow"><a href="../{listing}">← {label}</a></span><h1>{escape(x['name'])}</h1><p class="price">{price(x)}</p><p class="prose">{escape(x['description'][:1000])}</p><p class="small-note">Availability and final price are confirmed through Carmen’s current store. Artwork may have sold.</p><div class="detail-actions">{buy}<a class="textlink" href="{inquiry}">Ask Carmen about this piece ↗</a></div></div></section>'''
 save(p,x['name'],body,depth=1,desc=x['name']+' — original artwork by Carmen Wilde.')
# Homepage retains the approved direction and becomes a navigation hub for the complete site.
home='''<section class="hero shell"><div class="hero-copy"><span class="eyebrow">Canadian landscape artist · Edmonton, Alberta</span><h1>Into the <em>Wilde.</em></h1><p class="lead">Vivid landscapes for the places we go to feel alive. Original fine art inspired by Canada's wild beauty.</p><a class="button" href="originals.html">Explore original art <span aria-hidden="true">↗</span></a></div><div class="hero-art"><img src="assets/hero.webp" alt="Forest Alight, colourful landscape painting by Carmen Wilde"></div></section><div class="shell intro"><p>For the moments in nature that stay with you long after you leave.</p><small>Original art, made in Edmonton</small></div><section class="gallery shell" id="work"><div class="section-head"><div><span class="eyebrow">A glimpse into the collection</span><h2>Where the wild<br>takes us.</h2></div><a class="textlink" href="portfolio.html">View portfolio ↗</a></div><div class="gallery-grid"><figure class="work"><a class="work-link" href="portfolio.html"><img src="assets/empowered.webp" alt="Colourful painting of a waterfall"></a><figcaption><strong>Water & wilderness</strong><span>01 / 03</span></figcaption></figure><figure class="work"><a class="work-link" href="portfolio.html"><img src="assets/path.webp" alt="Painting of a path to water"></a><figcaption><strong>Fields & paths</strong><span>02 / 03</span></figcaption></figure><figure class="work"><a class="work-link" href="portfolio.html"><img src="assets/silence.webp" alt="Mountain landscape painting"></a><figcaption><strong>Mountains & stillness</strong><span>03 / 03</span></figcaption></figure></div></section><section class="about"><div class="shell about-inner"><div class="about-copy"><span class="eyebrow">Meet the artist</span><h2>A little closer<br>to <em>nature.</em></h2><p>Carmen Wilde is an Edmonton-based landscape artist drawn to the lakes, forests, fields, mountains, trails and coastlines of Canada. Her vivid paintings capture the discovery, tranquility and mystery of being in the wild.</p><a class="textlink" href="about.html">More about Carmen ↗</a></div><div class="about-visual"><img src="assets/blue.webp" alt="Colourful landscape painting"></div></div></section><section class="commission"><div class="commission-image"><img src="assets/forest.webp" alt="Forest landscape painting by Carmen Wilde"></div><div class="commission-copy"><span class="eyebrow">Made just for you</span><h2>A place. A memory.<br>Your story.</h2><p>Turn a meaningful photograph or place into a one-of-a-kind original painting. Carmen creates custom acrylic works in collaboration with you.</p><a class="button" href="commissions.html">Explore commissions <span aria-hidden="true">↗</span></a></div></section>'''
save('index.html','Art inspired by nature',home,desc="Carmen Wilde Fine Art. Edmonton landscape artist creating original acrylic paintings, commissions and art rentals inspired by Canada's wild beauty.",switcher=True)
# Portfolio: curated gallery leading to the complete original-painting catalog.
portfolio_items=[x for x in originals if x['slug'] in ['forest-alight','edge-of-silence','rock-on','outlook','choosing-a-path-1','river-ridge','fairytale-magic','before-the-day','alberta-bounty','chickakoo-i','breathe-autumn','reflective-moments-at-floating-stone']]
portfolio_items=portfolio_items or originals[:12]
save('portfolio.html','Portfolio',hero('Selected landscapes','An ode to <em>the wild.</em>','Explore a selection of Carmen’s vivid Canadian landscapes. The full collection includes original acrylic paintings and small works.')+'<section class="shell section-space"><div class="catalog">'+''.join(card(x) for x in portfolio_items)+'</div><a class="pill-link" href="originals.html">Browse all original paintings ↗</a></section>')
save('commissions.html','Commissions',hero('Custom original art','A memory made <em>lasting.</em>','Carmen creates custom acrylic paintings inspired by the photos, places and moments that mean the most to you.')+'''<section class="shell section-space split"><div class="prose"><h2>Artfully brought to life.</h2><p>Whether it’s a favourite vacation, a wedding memory or a meaningful landscape, a commissioned painting turns a personal experience into original art for your home.</p><p>Custom works range from 10 × 10 inches to 48 × 48 inches. Carmen works with you to understand the story behind your photograph, choose a suitable size and create a one-of-a-kind acrylic painting.</p><p>“I take the time to get to know you and understand what the photo means to you. We collaborate to make a statement art piece that reflects your vision.” — Carmen Wilde</p><a class="pill-link" href="contact.html?subject=Commission%20inquiry">Ask about a commission ↗</a></div><img class="split-art" src="assets/silence.webp" alt="Mountain landscape painting by Carmen Wilde"></section>''')
save('rentals.html','Art rentals',hero('Art rentals','Art for your <em>space.</em>','Bring original artwork into a staged home, sales centre or business.')+'''<section class="shell section-space split"><img class="split-art" src="assets/mountains.webp" alt="Panoramic mountain painting by Carmen Wilde"><div class="prose"><h2>Find the right fit.</h2><p>Carmen offers specialized art-rental rates and can help select artwork with the right proportions, colour and style for your interior.</p><p>Tell her about your space and timeline to discuss available pieces and rental options.</p><a class="pill-link" href="contact.html?subject=Art%20rental%20inquiry">Ask about rentals ↗</a></div></section>''')
save('about.html','About Carmen',hero('The artist','Carmen <em>Wilde.</em>','An Edmonton-based landscape artist drawn to the natural beauty of the wild.')+'''<section class="shell section-space split"><div class="prose"><h2>Inspired by nature.</h2><p>Carmen Wilde finds inspiration in Canada’s lakes, forests, fields, mountains, trails and coastlines. The feeling of retreating into wilderness — discovery, tranquility and mystery — runs through her paintings.</p><p>Her vivid use of colour sets the imagination alight. Carmen is also an accomplished interior designer with more than 30 years of experience in residential and commercial spaces through <a href="https://www.cwildedesigns.com/" target="_blank" rel="noopener noreferrer">C. Wilde Designs</a>.</p><a class="pill-link" href="contact.html">Get in touch ↗</a></div><img class="split-art portrait" src="assets/artist.webp" alt="Portrait of artist Carmen Wilde"></section>''')
contact='''<section class="shell contact-grid"><div class="prose"><h2>Let's talk art.</h2><p>Have a question about a painting, a commission or renting art for your space? Send Carmen a note.</p><p><a href="mailto:cwildedesigns@shaw.ca">cwildedesigns@shaw.ca</a></p><p class="small-note">The form opens your email app. Nothing is submitted or stored by this website.</p></div><form id="contact-form" class="form-row"><label>Your name<input name="name" autocomplete="name" required></label><label>Your email<input name="email" type="email" autocomplete="email" required></label><label>Message<textarea name="message" required></textarea></label><button class="button" type="submit">Compose email ↗</button></form></section><script>document.getElementById('contact-form').addEventListener('submit',function(e){e.preventDefault();const d=new FormData(this);const q=new URLSearchParams(location.search);const subject=q.get('subject')||'Fine art inquiry';location.href='mailto:cwildedesigns@shaw.ca?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent('From: '+d.get('name')+' ('+d.get('email')+')\\n\\n'+d.get('message'))});</script>'''
save('contact.html','Contact Carmen',hero('Get in touch','Say <em>hello.</em>','We’d love to hear what caught your eye.' )+contact)
save('faq.html','Frequently asked questions',hero('Helpful details','Questions & <em>answers.</em>','A few practical notes about original artwork, commissions and ordering.')+'''<section class="shell section-space prose"><details class="faq-item"><summary>What does original fine art cost?</summary><p>As a guide, Carmen’s published rates are typically $1.00 per square inch for smaller pieces and $1.50 per square inch for larger works. Examples from the current FAQ: 8 × 10 inches — $80; 12 × 12 — $144; 16 × 20 — $480; 16 × 40 — $960; 24 × 48 — $1,728; 48 × 36 — $2,592; 48 × 60 — $4,320. Confirm the final quote directly with Carmen.</p></details><details class="faq-item"><summary>Can I commission a painting?</summary><p>Yes. Carmen creates custom acrylic works based on a meaningful photograph or place. <a href="commissions.html">Learn about commissions</a> or <a href="contact.html?subject=Commission%20inquiry">send an inquiry</a>.</p></details><details class="faq-item"><summary>How do commissions work?</summary><p>Commissioned paintings start at $1.50 per square inch. Carmen paints an original interpretation of your photo, not a photo-finish reproduction. In-person or virtual consultations start at $125 per hour; remote clients can email or mail a photograph and consult virtually. Please confirm current rates and details directly with Carmen.</p></details><details class="faq-item"><summary>Do you offer art rentals?</summary><p>Yes. Rentals are available for staging, sales centres and businesses; rates and selections are discussed individually. <a href="rentals.html">See art rentals</a>.</p></details><details class="faq-item"><summary>How does shipping work?</summary><p>Domestic shipping within Canada is offered for a flat fee. Local Edmonton-area delivery may also be available for a flat fee. <a href="shipping-returns.html">Read the shipping policy</a>.</p></details></section>''')
save('shipping-returns.html','Shipping & returns',hero('Practical details','Shipping & <em>returns.</em>','Information from Carmen’s existing store policy.')+'''<section class="shell section-space prose legal"><h2>Shipping policy</h2><p>Shipping within Canada is offered for a flat fee. Delivery within Edmonton and the surrounding area may also be provided for a flat fee. Please <a href="contact.html">contact Carmen</a> for details and a quote.</p><h2>Returns & exchanges</h2><p>Due to the custom nature of the artwork, returns are not accepted at this time.</p></section>''')
save('terms-conditions.html','Terms & conditions',hero('Practical details','Terms & <em>conditions.</em>','Policies and payment information from Carmen’s existing site.')+'''<section class="shell section-space prose legal"><h2>Privacy & safety</h2><p>This static website does not store contact-form entries or payment information. The contact form opens your own email application, and messages you send are handled by your and Carmen’s email providers. GitHub Pages hosts this website and Google Fonts supplies its typography; those providers may receive standard technical requests when you visit. For purchases, the existing Wix store handles checkout and payment information. <a href="https://www.carmenwildefineart.com/terms-conditions" target="_blank" rel="noopener noreferrer">Read the current store’s terms ↗</a>.</p><h2>Payment methods</h2><p>Credit and debit cards are supported through the current online store. E-transfers and offline payments may be arranged directly with Carmen.</p><p>Online checkout currently takes place on the existing store. This GitHub-hosted website does not collect payment details.</p></section>''')
print('Built',len(products),'artwork pages plus site pages')
